<template>
  <div class="demo-page"><el-card shadow="never" :body-style="{ display: 'none' }"><template #header><div class="head"><div class="title">加速故障复现</div><el-tag :type="online?'success':'danger'">{{online?'Agent 在线':'Agent 离线'}}</el-tag></div></template></el-card>
    <el-card v-for="s in cards" :key="s.sample_id" shadow="never" class="sample"><div class="head"><div class="sample-title">{{s.title}}</div><div><el-button size="small" :disabled="busy" @click="preview(s)">查看样例</el-button><el-button type="success" size="small" :disabled="!online||busy" @click="reproduce(s,'normal')">正常复现</el-button><el-button type="warning" size="small" :disabled="!online||!s.normalJobId||busy" @click="reproduce(s,'checkpoint_demo')">加速复现</el-button></div></div><div class="actions"><el-button size="small" :disabled="!s.latestJobId" @click="view(s.latestJobId)">查看任务</el-button><el-button type="danger" plain size="small" :disabled="!s.runningJobId" @click="cancel(s.runningJobId)">停止任务</el-button><el-button type="primary" plain size="small" :disabled="!s.completedJobId" @click="download(s.completedJobId)">下载产物</el-button></div></el-card>
    <el-drawer v-model="show" title="样例预览" size="520px"><pre>{{JSON.stringify(previewData,null,2)}}</pre></el-drawer><el-drawer v-model="taskDrawer" title="复现任务详情" size="580px"><el-descriptions v-if="selected" :column="1" border><el-descriptions-item label="任务 ID">{{selected.job_id}}</el-descriptions-item><el-descriptions-item label="状态">{{selected.status}}</el-descriptions-item><el-descriptions-item label="正常耗时">{{seconds(selected.normal_wall_duration_seconds)}}</el-descriptions-item><el-descriptions-item label="复现耗时">{{seconds(selected.replay_wall_duration_seconds)}}</el-descriptions-item><el-descriptions-item label="实测倍率">{{ratio(selected.measured_speedup)}}</el-descriptions-item><el-descriptions-item label="来源任务">{{selected.source_job_id||'-'}}</el-descriptions-item></el-descriptions><el-divider content-position="left">执行事件</el-divider><el-timeline v-if="events.length"><el-timeline-item v-for="(e,i) in events" :key="i" :timestamp="e.timestamp">{{e.stage}} · {{e.status}} · {{e.message}}</el-timeline-item></el-timeline><el-empty v-else description="暂无事件" /></el-drawer>
  </div>
</template>
<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {cancelVirtualPrototypeJob,downloadVirtualPrototypeArtifact,getVirtualPrototypeEvents,getVirtualPrototypeHealth,listVirtualPrototypeJobs,listVirtualPrototypeSamples,replayVirtualPrototypeJob,reproduceVirtualPrototypeSample,getVirtualPrototypeJob} from '@/api/virtualPrototype';import localPreviews from '@/data/eulerSamplePreviews.json'
const fallback=[{sample_id:'sample-f4512-high-load',title:'持续高系统负载',replay_fault_type:'F4512'},{sample_id:'sample-f4620-memory',title:'可用内存枯竭',replay_fault_type:'F4620'},{sample_id:'sample-f5313-tcp',title:'TCP 连接失败',replay_fault_type:'F5313'}]
const online=ref(false),samples=ref(fallback),jobs=ref([]),show=ref(false),previewData=ref(null),busy=ref(false),taskDrawer=ref(false),selected=ref(null),events=ref([]);const normalSources=ref(loadStorage('checkpoint-demo-sources'));const latestReplay=ref(loadStorage('checkpoint-demo-latest'));let timer,taskTimer,selectedId=''
function loadStorage(key){if(typeof localStorage==='undefined')return {};try{const value=JSON.parse(localStorage.getItem(key)||'{}');return value&&typeof value==='object'?value:{}}catch{return {}}}
function rememberReplay(sampleId,jobId,mode){if(!sampleId||!jobId)return;latestReplay.value={...latestReplay.value,[sampleId]:{job_id:jobId,mode}};if(typeof localStorage!=='undefined')localStorage.setItem('checkpoint-demo-latest',JSON.stringify(latestReplay.value))}
function jobTime(job){const value=job?.created_at||job?.job?.created_at||job?.summary?.created_at;const time=value?Date.parse(value):NaN;return Number.isFinite(time)?time:0}
const cards=computed(()=>samples.value.map(s=>{const a=jobs.value.filter(j=>j.job?.sample_id===s.sample_id||j.sample_id===s.sample_id).sort((x,y)=>jobTime(y)-jobTime(x)||String(y.job_id||'').localeCompare(String(x.job_id||'')));const source=normalSources.value[s.sample_id];const n=a.find(j=>j.job_id===source&&j.job?.reproduction_mode==='normal'&&j.status==='succeeded');const r=a.find(j=>['queued','preparing','running','finalizing','cancel_requested'].includes(j.status));const remembered=latestReplay.value[s.sample_id]?.job_id;const latest=remembered||a[0]?.job_id;const current=a.find(j=>j.job_id===latest);const c=['succeeded','acceleration_target_not_met'].includes(current?.status)&&current?.artifact_path&&!current?.artifact_error?current:undefined;return {...s,normalJobId:n?.job_id,runningJobId:r?.job_id,latestJobId:latest,completedJobId:c?.job_id}}));
async function load(){let healthy=false;try{await getVirtualPrototypeHealth();healthy=true}catch(e){healthy=false}online.value=healthy;if(healthy){try{samples.value=(await listVirtualPrototypeSamples()).samples||fallback}catch(e){/* keep local catalog */}}else samples.value=fallback}
async function refresh(){try{jobs.value=(await listVirtualPrototypeJobs({limit:100,offset:0})).jobs||[]}catch(e){/* /healthz is the sole online signal */}}
async function reproduce(s,mode){busy.value=true;try{let x;if(mode==='normal'){x=await reproduceVirtualPrototypeSample(s.sample_id,{reproduction_mode:'normal',evidence_mode:'simulated'});normalSources.value={...normalSources.value,[s.sample_id]:x.job_id};localStorage.setItem('checkpoint-demo-sources',JSON.stringify(normalSources.value))}else{x=await replayVirtualPrototypeJob(s.normalJobId,{execution_mode:'checkpoint_demo',sample_count:1})}rememberReplay(s.sample_id,x.job_id,mode);ElMessage.success(`复现任务已提交：${x.job_id}`);await refresh();await view(x.job_id)}catch(e){ElMessage.error(e.response?.data?.detail||'复现提交失败')}finally{busy.value=false}}
function preview(s){const payload=localPreviews[s.sample_id];if(!payload){ElMessage.error('本地样例预览不可用');return}previewData.value=payload;show.value=true}
function terminal(status){return ['succeeded','partial_failed','failed','cancelled','interrupted','capability_failed','acceleration_target_not_met'].includes(status)}
async function loadTask(id,showError=false){try{const [job,event]=await Promise.all([getVirtualPrototypeJob(id),getVirtualPrototypeEvents(id)]);if(selectedId!==id)return;selected.value=job;events.value=event.events||[];if(terminal(job.status))stopTaskPolling();return job}catch(e){if(showError)ElMessage.error(e.response?.data?.detail||'任务查询失败');return null}}
function stopTaskPolling(){if(taskTimer){clearInterval(taskTimer);taskTimer=null}}
function startTaskPolling(id){stopTaskPolling();taskTimer=setInterval(()=>{if(taskDrawer.value)loadTask(id);else stopTaskPolling()},1200)}
async function view(id){if(!id)return;selectedId=id;taskDrawer.value=true;const job=await loadTask(id,true);if(job&&!terminal(job.status))startTaskPolling(id)}
async function cancel(id){try{await ElMessageBox.confirm('确认停止任务？','停止任务',{type:'warning'});await cancelVirtualPrototypeJob(id);await refresh();if(selectedId===id)await loadTask(id)}catch(e){if(e!=='cancel')ElMessage.error('停止请求失败')}}
async function download(id){try{const x=await downloadVirtualPrototypeArtifact(id);const u=URL.createObjectURL(x.data||x);const a=document.createElement('a');a.href=u;a.download=`${id}.tar.gz`;a.click();URL.revokeObjectURL(u)}catch(e){ElMessage.error(e.response?.data?.detail||'下载失败')}}
onMounted(()=>{load();refresh();timer=setInterval(refresh,3000)});onUnmounted(()=>{clearInterval(timer);stopTaskPolling()})
function seconds(v){return typeof v==='number'?`${v.toFixed(3)} 秒`:'-'}function ratio(v){return typeof v==='number'?`${v.toFixed(2)} 倍`:'-'}
</script><style scoped>.demo-page{display:flex;flex-direction:column;gap:16px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px}.title{font-size:18px;font-weight:650}.sample-title{font-size:16px;font-weight:600}.sub{color:#64748b;font-size:13px;margin-top:5px}.actions{margin-top:14px}pre{white-space:pre-wrap;max-height:80vh;overflow:auto}</style>
